   "id": "traits",
   "title": "A trait and a bound",
   "blurb": "Generics monomorphize: one `announce` in the source becomes one machine function per concrete type, which you can find by name in the IR.",
   "file": "examples/tour/traits.yoop",
   "source": "// A trait is a capability: the operations a type promises to provide. It is\n// the only polymorphism there is. No classes, no inheritance.\n\ntrait Greeter {\n  function greet(ref self): string;\n}\n\n// A type opts in with `implements` and supplies the bodies inline. Methods\n// take `ref self` first.\ntype Town implements Greeter {\n  name: string,\n  population: int32,\n  function greet(ref self): string {\n    return self.name;\n  }\n}\n\ntype Lake implements Greeter {\n  name: string,\n  function greet(ref self): string {\n    return self.name;\n  }\n}\n\n// The reason traits exist: one function, any type that satisfies the bound.\n// It is monomorphized, so there is no runtime dispatch.\n//\n// Calls are trait-qualified - `Greeter.greet(ref g)`, never `g.greet()`. The\n// trait name at the call site is what lets two traits on one type both have a\n// `greet` with no ambiguity.\nfunction announce<T implements Greeter>(ref g: T): void {\n  printf(`hello from ${Greeter.greet(ref g)}\\n`);\n}\n\nfunction main(): int32 {\n  let mqt: Town = { name: \"Marquette\", population: 20629 };\n  let superior: Lake = { name: \"Lake Superior\" };\n\n  announce(ref mqt);\n  announce(ref superior);\n\n  printf(`${mqt.name} has ${mqt.population} people\\n`);\n  return 0;\n}\n",
